<?php declare(strict_types=1);use Cms\Core\Theme\TemplateContext;/** @var TemplateContext $context */require_once dirname(__DIR__).'/_theme.php';$seo=$context->seo();$items=dj_items($context);$pagination=$context->get('pagination',[]);?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $context->e((string)($seo['title']??'典籍')) ?></title><link rel="stylesheet" href="<?= $context->e($context->asset('css/style.css')) ?>"></head><body class="dj-theme dj-paper-page"><?php require dirname(__DIR__).'/partials/header.php';?><main class="dj-list"><div class="dj-page-heading"><span>DAOJIA</span><h1><?= $context->e((string)$context->get('page_title','搜索结果')) ?></h1></div><div class="dj-grid"><?php foreach($items as $item):$u=dj_content_url($item);?><article class="dj-card"><div><time><?= $context->e(dj_date($item['published_at']??$item['created_at']??'')) ?></time><h2><a href="<?= $context->e($u) ?>"><?= $context->e((string)($item['title']??'')) ?></a></h2><p><?= $context->e(dj_excerpt($item)) ?></p><a class="dj-read" href="<?= $context->e($u) ?>">阅读全文 →</a></div></article><?php endforeach;?></div><?php if(is_array($pagination)&&!empty($pagination['pages'])):?><nav class="dj-pagination" aria-label="分页"><?php foreach($pagination['pages'] as $p):?><a href="<?= $context->e((string)($p['url']??'')) ?>"<?= !empty($p['current'])?' aria-current="page"':'' ?>><?= $context->e((string)($p['label']??$p['page']??'')) ?></a><?php endforeach;?></nav><?php endif;?></main><?php require dirname(__DIR__).'/partials/footer.php';?><script defer src="<?= $context->e($context->asset('js/daojia.js')) ?>"></script></body></html>